    static TreeSet<Long> set = new TreeSet<>();
    static long x, y, l, r;

    static void generate(BigInteger base, long max, TreeSet<Long> s) {
        BigInteger cur = BigInteger.ONE;
        while (cur.compareTo(BigInteger.valueOf(max)) <= 0) {
            s.add(cur.longValue());
            if (base.equals(BigInteger.ONE)) break;
            cur = cur.multiply(base);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        x = sc.nextLong();
        y = sc.nextLong();
        l = sc.nextLong();
        r = sc.nextLong();

        TreeSet<Long> xs = new TreeSet<>();
        TreeSet<Long> ys = new TreeSet<>();
        generate(BigInteger.valueOf(x), r, xs);
        generate(BigInteger.valueOf(y), r, ys);

        for (Long a : xs) {
            for (Long b : ys) {
                if (a > r - b) break;
                long sum = a + b;
                if (sum >= l && sum <= r) {
                    set.add(sum);
                }
            }
        }

        long maxGap = 0;
        long prev = l - 1;
        for (Long cur : set) {
            if (cur > r) break;
            if (cur < l) continue;
            maxGap = Math.max(maxGap, cur - prev - 1);
            prev = cur;
        }
        maxGap = Math.max(maxGap, r - prev);

        System.out.println(maxGap);
    }
